1	import Anthropic from '@anthropic-ai/sdk';
2	import type { Message, MessageCreateParamsNonStreaming } from '@anthropic-ai/sdk/resources/messages/messages.js';
3	
4	// ---------------------------------------------------------------------------
5	// Public types
6	// ---------------------------------------------------------------------------
7	
8	export interface LLMOptions {
9	  model?: string;
10	  maxTokens?: number;
11	  temperature?: number;
12	  timeout?: number;
13	}
14	
15	export interface LLMResponse {
16	  content: string;
17	  model: string;
18	  usage: {
19	    inputTokens: number;
20	    outputTokens: number;
21	  };
22	  durationMs: number;
23	}
24	
25	export interface LLMClientConfig {
26	  maxRetries?: number;   // default 3
27	  baseDelayMs?: number;  // default 1000
28	  apiKey?: string;       // default process.env.ANTHROPIC_API_KEY
29	}
30	
31	// ---------------------------------------------------------------------------
32	// Client
33	// ---------------------------------------------------------------------------
34	
35	const DEFAULT_MODEL = 'claude-sonnet-4-20250514';
36	const DEFAULT_MAX_TOKENS = 1024;
37	
38	export class LLMClient {
39	  private readonly anthropic: Anthropic;
40	  private readonly maxRetries: number;
41	  private readonly baseDelayMs: number;
42	
43	  /**
44	   * @param config         Public config options.
45	   * @param config.anthropic  Optional pre-configured Anthropic SDK instance
46	   *                          (used for dependency injection / testing).
47	   */
48	  constructor(
49	    config?: LLMClientConfig & { anthropic?: Anthropic },
50	  ) {
51	    this.maxRetries = config?.maxRetries ?? 3;
52	    this.baseDelayMs = config?.baseDelayMs ?? 1000;
53	
54	    if (config?.anthropic) {
55	      this.anthropic = config.anthropic;
56	    } else {
57	      this.anthropic = new Anthropic({
58	        apiKey: config?.apiKey ?? process.env.ANTHROPIC_API_KEY,
59	      });
60	    }
61	  }
62	
63	  // -----------------------------------------------------------------------
64	  // Public API
65	  // -----------------------------------------------------------------------
66	
67	  /**
68	   * Send a prompt to the LLM and receive a structured response.
69	   * Automatically retries on retry-able errors (network timeout, 429, 5xx).
70	   */
71	  async send(prompt: string, options?: LLMOptions): Promise<LLMResponse> {
72	    const startTime = Date.now();
73	
74	    for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
75	      try {
76	        const body: MessageCreateParamsNonStreaming = {
77	          model: options?.model ?? DEFAULT_MODEL,
78	          max_tokens: options?.maxTokens ?? DEFAULT_MAX_TOKENS,
79	          messages: [{ role: 'user', content: prompt }],
80	          ...(options?.temperature !== undefined ? { temperature: options.temperature } : {}),
81	        };
82	
83	        const response = await this.anthropic.messages.create(body, {
84	          timeout: options?.timeout,
85	        });
86	
87	        const durationMs = Date.now() - startTime;
88	        const content = (response.content as Array<{ type: string; text?: string }>)
89	          .filter((b) => b.type === 'text')
90	          .map((b) => b.text ?? '')
91	          .join('');
92	
93	        return {
94	          content,
95	          model: response.model,
96	          usage: {
97	            inputTokens: response.usage.input_tokens,
98	            outputTokens: response.usage.output_tokens,
99	          },
100	          durationMs,
101	        };
102	      } catch (err: unknown) {
103	        // If this is the last attempt, rethrow immediately.
104	        if (attempt >= this.maxRetries || !this.isRetryable(err)) {
105	          throw err;
106	        }
107	
108	        const delayMs = this.baseDelayMs * Math.pow(2, attempt);
109	        console.log(
110	          `[WARN] LLM call failed (attempt ${attempt + 1}/${this.maxRetries + 1}), retrying in ${delayMs}ms: ${(err as Error).message}`,
111	        );
112	        await this.sleep(delayMs);
113	      }
114	    }
115	
116	    // Unreachable -- the loop always returns or throws.
117	    throw new Error('Unexpected state in LLMClient.send');
118	  }
119	
120	  // -----------------------------------------------------------------------
121	  // Static factory
122	  // -----------------------------------------------------------------------
123	
124	  /**
125	   * Create a mock LLMClient that does **not** make real API calls.
126	   *
127	   * @param stubResponse  Return this LLMResponse on success, or throw this
128	   *                      Error on failure.  The full retry machinery is still
129	   *                      active so you can test retry exhaustion.
130	   */
131	  static createMock(stubResponse: LLMResponse | Error): LLMClient {
132	    const mockAnthropic = {
133	      messages: {
134	        create: async (): Promise<Message> => {
135	          if (stubResponse instanceof Error) {
136	            throw stubResponse;
137	          }
138	          return {
139	            id: 'mock_msg_id',
140	            type: 'message',
141	            role: 'assistant',
142	            content: [{ type: 'text', text: stubResponse.content }],
143	            model: stubResponse.model,
144	            usage: {
145	              input_tokens: stubResponse.usage.inputTokens,
146	              output_tokens: stubResponse.usage.outputTokens,
147	            },
148	          } as Message;
149	        },
150	      },
151	    };
152	
153	    return new LLMClient({ anthropic: mockAnthropic as unknown as Anthropic });
154	  }
155	
156	  // -----------------------------------------------------------------------
157	  // Private helpers
158	  // -----------------------------------------------------------------------
159	
160	  /**
161	   * Determine whether an error is worth retrying.
162	   *
163	   * Retry-able:
164	   *   - Network / connection errors  (status === undefined)
165	   *   - HTTP 429 (rate-limit)
166	   *   - HTTP 5xx (server errors)
167	   *
168	   * Non-retry-able (thrown immediately):
169	   *   - HTTP 401 (auth)
170	   *   - HTTP 403 (permission)
171	   *   - HTTP 400 (bad request)
172	   */
173	  private isRetryable(err: unknown): boolean {
174	    const error = err as { status?: number };
175	    const status = error.status;
176	
177	    // Non-retry-able status codes
178	    if (status === 401 || status === 403 || status === 400) {
179	      return false;
180	    }
181	
182	    // Retry-able: rate limits, server errors, network timeouts
183	    if (status === 429) return true;
184	    if (status !== undefined && status >= 500) return true;
185	    if (status === undefined) return true; // e.g. APIConnectionTimeoutError
186	
187	    return false;
188	  }
189	
190	  /** Promise-based delay for retry back-off. */
191	  private sleep(ms: number): Promise<void> {
192	    return new Promise((resolve) => setTimeout(resolve, ms));
193	  }
194	}
